-- ===========================================================================
-- db_katala -> PostgreSQL (Supabase) migration
-- Converted from: db_katala.sql (MySQL dump, schema only)
-- Run in the Supabase SQL editor, or: psql -f migration.sql
--
-- Key conversions:
--   BIGINT UNSIGNED AUTO_INCREMENT  ->  BIGINT GENERATED BY DEFAULT AS IDENTITY
--   DATETIME                        ->  TIMESTAMP
--   ENGINE=InnoDB / backticks       ->  removed
--   TINYINT(1) BOOLEAN flag columns ->  SMALLINT NOT NULL DEFAULT 1
--                                      (Laravel compares v_isActive with 1/0)
--   ENUM('delivery','pickup')       ->  fulfillment_type enum
--   ON UPDATE CURRENT_TIMESTAMP     ->  set_updated_at() trigger (18 tables)
--   Inline INDEX / UNIQUE KEY       ->  CREATE [UNIQUE] INDEX ... IF NOT EXISTS
--
-- IMPORTANT: Every identifier is double-quoted with the EXACT case used by the
-- Laravel models/controllers (e.g. "tbl_serviceRequest", "v_customerId").
-- PostgreSQL folds unquoted identifiers to lowercase while Laravel's Postgres
-- grammar always quotes identifiers, so the case must match the MySQL dump.
--
-- NOTE for when the Laravel backend is eventually pointed at this database:
-- the raw CONCAT() columns in AdminDataController (dashboard / requests) must
-- quote the column names: COALESCE(c."v_firstName", ...), COALESCE(c."v_lastName", ...).
--
-- All DROP statements are hoisted to the top so the script is re-runnable.
-- After running this, run `php artisan migrate` to create the Sanctum
-- personal_access_tokens table.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- Timestamp helper: mimics MySQL's ON UPDATE CURRENT_TIMESTAMP.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW."v_updatedAt" = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ---------------------------------------------------------------------------
-- Enum used by "tbl_deliveryPickup"."v_fulfillmentType".
-- ---------------------------------------------------------------------------
DO $$
BEGIN
    CREATE TYPE fulfillment_type AS ENUM ('delivery', 'pickup');
EXCEPTION
    WHEN duplicate_object THEN NULL;
END $$;

-- ---------------------------------------------------------------------------
-- Drop everything first (CASCADE so referencing foreign keys go too).
