DROP TABLE IF EXISTS "tbl_materialPriceHistory" CASCADE;
DROP TABLE IF EXISTS "tbl_quotation" CASCADE;
DROP TABLE IF EXISTS "tbl_quotationItem" CASCADE;
DROP TABLE IF EXISTS "tbl_project" CASCADE;
DROP TABLE IF EXISTS "tbl_projectMaterial" CASCADE;
DROP TABLE IF EXISTS "tbl_payment" CASCADE;
DROP TABLE IF EXISTS "tbl_projectBilling" CASCADE;
DROP TABLE IF EXISTS "tbl_inventory" CASCADE;
